function make(title, category, summary, body, ref) {
  const [sourceTitle, url, type, description] = refs[ref];
  return {
    category, subject: title, articleTitle: title, articleSummary: summary, articleBody: body,
    articleSources: [{ title: sourceTitle, url, type, description }],
  };
}

const technologyArticles = [
  make("Компілятор і шлях від коду до виконання", "Мови та виконання", "Компілятор перетворює програму з опису, зручного для людини, на форму, яку може виконати конкретна обчислювальна платформа.", "Компіляція розв’язує задачу перевірки та перетворення вихідного тексту до виконуваного представлення. У типовому процесі фронтенд аналізує символи й граматику, будує внутрішнє подання та перевіряє семантичні обмеження; бекенд оптимізує представлення і генерує об’єктний або машинний код. Межі цих етапів залежать від мови: частина систем компілює до байткоду, інші — безпосередньо до машинних інструкцій.\n\nНаприклад, компілятор може повідомити про невизначену змінну до запуску програми, тоді як помилку мережевого доступу виявить лише час виконання. QA перевіряє відтворюваність складання, відповідність цільовій платформі, символи налагодження та те, що артефакт справді походить із заявленого коміту. Різні прапорці компіляції, версії компілятора й бібліотек можуть змінювати поведінку або характеристики програми, тому їх слід фіксувати як частину конфігурації випуску.", "llvm"),
  make("Лексичний аналіз, синтаксис і абстрактне дерево", "Мови та виконання", "Фронтенд компілятора перетворює послідовність символів на структуру програми та встановлює її синтаксичні й семантичні відношення.", "Лексичний аналізатор групує символи в токени, парсер зіставляє їх із граматикою, а абстрактне синтаксичне дерево представляє вкладені конструкції без зайвих деталей форматування. Після синтаксичного аналізу компілятор перевіряє області видимості, типи, сигнатури та правила мови. Ці стадії дають різні класи діагностичних помилок і формують межу між некоректним текстом та програмою, яку можна перетворювати далі.\n\nУмовна функція з відсутньою дужкою є синтаксичною помилкою, а передавання рядка параметру числового типу може бути помилкою типізації. Тестування компілятора та інструментів розробки враховує локалізацію повідомлень, стабільність діагностики, обробку великих файлів і граничних конструкцій граматики. Для QA важливо не плутати помилку аналізатора із дефектом програми: спочатку потрібно перевірити, чи прийняв компілятор вихідний текст і який саме артефакт було створено.", "llvm"),
  make("Система типів і статичний аналіз", "Мови та виконання", "Система типів обмежує допустимі операції над значеннями, а статичний аналіз виявляє певні ризики до фактичного запуску програми.", "Перевірка типів може відбуватися під час компіляції або частково під час виконання. Статичні аналізатори доповнюють її правилами, які шукають недосяжний код, небезпечні перетворення, можливе розіменування відсутнього значення чи порушення домовленостей команди. Такий аналіз не доводить загальну правильність програми: його висновок обмежений моделлю та правилами конкретного інструмента.\n\nЯкщо аналізатор позначив потенційно небезпечну гілку, QA має з’ясувати, чи можна створити вхідні дані, що приводять до неї, і чи відповідає сигнал фактичному ризику. Надто агресивне правило породжує хибні спрацювання, а надто поблажливе — пропускає дефекти. Перевіряйте версії набору правил, винятки, інтеграцію в збірку та однаковість результатів локально й у CI. Аналізатор є шаром раннього зворотного зв’язку, а не заміною динамічних тестів і рев’ю вимог.", "llvm"),
  make("Проміжне представлення та оптимізація компілятора", "Мови та виконання", "Проміжне представлення відокремлює особливості вихідної мови від архітектури процесора та дає змогу застосовувати спільні перетворення.", "Компілятор може знизити абстрактне дерево до проміжного представлення, придатного для аналізу потоку керування, залежностей і використання значень. На ньому виконують усунення мертвого коду, спрощення виразів, вбудовування функцій та інші оптимізації, після чого бекенд перетворює результат відповідно до цільового набору інструкцій. Оптимізація має зберігати семантику програми за визначеної моделлю мови поведінки.\n\nДля QA корисно порівнювати результати збірки з оптимізацією та без неї, особливо для переповнення, конкурентного доступу, роботи з пам’яттю й невизначеної поведінки. Відмінність у часі виконання сама по собі не означає дефект; важливі відтворювані результати та відповідність специфікації. Порівняння проміжного представлення й машинного коду допомагає локалізувати проблему між фронтендом, оптимізатором, бекендом і середовищем виконання.", "llvm"),
  make("Генерація коду, асемблер і компонувальник", "Мови та виконання", "Після оптимізації компілятор генерує об’єктний код, а компонувальник поєднує його з бібліотеками в програмний артефакт.", "Об’єктний файл містить машинні інструкції, таблиці символів і посилання, які ще можуть потребувати розв’язання. Статичне компонування включає потрібний код бібліотек у кінцевий артефакт, а динамічне залишає залежність від бібліотек, що завантажуються в середовищі запуску. Відмінність впливає на розмір, оновлення, сумісність і поверхню безпеки програми.\n\nЯкщо застосунок працює на машині розробника, але падає в контейнері, перевірте архітектуру процесора, ABI, наявність потрібних бібліотек і відповідність версій. QA може досліджувати таблиці залежностей, коди завершення та символи налагодження, не роблячи висновок лише з успішної компіляції. Відтворюване складання та перевірка підписаного кінцевого артефакту дають змогу підтвердити, що саме тестований файл був опублікований.", "llvm"),
  make("Байткод і віртуальна машина", "Мови та виконання", "Байткод є стандартизованим набором інструкцій для віртуальної машини, який не прив’язаний безпосередньо до конкретного процесора.", "Мова може компілювати вихідний код у байткод, а віртуальна машина завантажує його, перевіряє формат і виконує за правилами специфікації. Наприклад, JVM визначає стеки потоків, купу об’єктів, кадри викликів і формат class-файлів, але конкретна реалізація може інтерпретувати інструкції або перекладати їх у машинний код. Тому стандартний байткод і реалізація середовища виконання є різними рівнями системи.\n\nДля діагностики дефекту важливо зафіксувати версію байткоду, віртуальної машини, параметри запуску та платформу. Однаковий артефакт може демонструвати різну продуктивність на різних реалізаціях, хоча його семантика має залишатися сумісною зі специфікацією. QA перевіряє також поведінку завантажувачів класів, винятки під час ініціалізації, сумісність бібліотек і коректну обробку помилкового або пошкодженого байткоду.", "jvm"),
  make("JIT-компіляція та профілювання під час виконання", "Мови та виконання", "JIT-компілятор перетворює часто виконуваний байткод або проміжний код на машинні інструкції вже під час роботи програми.", "На початку виконання система може інтерпретувати код або застосувати базову компіляцію, збираючи статистику про гарячі функції та фактичні типи. Оптимізувальний JIT використовує ці спостереження, але має зберігати можливість деоптимізації, коли припущення перестає бути істинним. Вартість компіляції та прогріву означає, що перші запити часто відрізняються від усталеного режиму.\n\nЯкщо затримка високою є лише на перших запитах, порівняйте холодний старт із прогрітим станом і зафіксуйте JIT-компіляцію, кеш класів та завантаження бібліотек. Для QA важливо відокремити час ініціалізації від часу обробки запиту, а також перевірити, що деоптимізація не змінює результат. Один короткий бенчмарк після запуску не характеризує стабільну продуктивність системи.", "jvm"),
  make("Керування пам’яттю та збирач сміття", "Мови та виконання", "Збирач сміття автоматично звільняє пам’ять об’єктів, які більше не досяжні програмою, але не керує всіма зовнішніми ресурсами.", "Середовище виконання виявляє досяжність об’єктів від коренів, визначених потоками й глобальним станом, після чого повертає пам’ять для повторного використання. Різні збирачі обирають компроміс між пропускною здатністю, затримками пауз, фрагментацією та споживанням пам’яті. Вивільнення файлового дескриптора або транзакції не слід покладати на момент збору сміття, оскільки він не гарантований у потрібний час.\n\nПід час тестування довготривалого сервісу відстежуйте розмір купи, частоту й тривалість зборів, паузи, витік посилань і використання нативної пам’яті. Зростання купи не обов’язково є витоком, якщо пам’ять звільняється після циклу навантаження. Відтворюваний дефект потребує кореляції метрик збирача з кількістю запитів і даними, що залишилися досяжними.", "jvm"),
  make("Процеси, потоки та системні виклики", "Операційна система", "Операційна система надає процесам ізольований простір виконання, а системні виклики забезпечують контрольований доступ до ресурсів ядра.", "Процес має адресний простір і набір ресурсів, тоді як потоки в межах процесу зазвичай спільно використовують пам’ять та відкриті ресурси. Системні виклики надають операції з файлами, мережею, пам’яттю й керуванням дочірніми процесами. Конкурентне виконання підвищує пропускну здатність, але породжує змагання за спільний стан, блокування та взаємні блокування.\n\nКоли навантажувальний тест виявляє зависання, корисно зіставити кількість потоків, очікування блокувань, відкриті дескриптори та системне навантаження. QA перевіряє межі конкурентності, завершення процесів, повторне використання ресурсів і коректну реакцію на сигнали зупинки. Перезапуск процесу може приховати витік ресурсу, тому тестуйте повторювані цикли запуску й завершення, а не лише одиничний happy path.", "linux"),
  make("Файлова система та довговічність даних", "Операційна система", "Файлова система організує іменовані дані та метадані на носії, проте успішний запис у буфер не завжди означає фізичну довговічність.", "Процес відкриває файл через файловий дескриптор, а ядро кешує операції перед передаванням їх пристрою зберігання. Права доступу, блокування, атомарне перейменування, синхронізація запису й поведінка файлової системи впливають на результат під час збою живлення або завершення процесу. Контейнерні шари файлової системи можуть бути тимчасовими, якщо окремий том не змонтовано.\n\nДля перевірки сховища відтворіть перезапуск сервісу після запису, відмову диска, нестачу місця та відновлення з резервної копії. Зіставляйте прикладні підтвердження з фактичним вмістом після перезапуску. QA має перевірити власника, права та точку монтування, оскільки контейнер може успішно записати дані у тимчасовий шар, який буде втрачено після видалення контейнера.", "linux"),
  make("Контейнерний runtime та специфікація OCI", "Інфраструктура", "Контейнерний runtime створює ізольований процес за конфігурацією образу, тоді як специфікації OCI стандартизують формати образу й життєвий цикл запуску.", "Контейнер не є повною віртуальною машиною: він використовує ядро хостової операційної системи та ізоляційні механізми на кшталт namespaces і cgroups. Вищорівневий рушій готує образ і конфігурацію, а runtime створює процес, налаштовує середовище, монтування й обмеження ресурсів. Сумісність формату не означає тотожність усіх параметрів безпеки між різними runtime.\n\nQA перевіряє користувача процесу, capabilities, змонтовані каталоги, мережеві правила, ліміти CPU і пам’яті та поведінку при завершенні. Наприклад, контейнер, що працює з привілеями адміністратора, може збільшити вплив вразливості застосунку на хост. Порівнюйте конфігурацію фактично запущеного контейнера із задекларованою, а також перевіряйте graceful shutdown і очищення ресурсів.", "oci"),
  make("Образи контейнерів і відтворювані складання", "Інфраструктура", "Образ контейнера є незмінним пакетом файлової системи та метаданих, з якого runtime створює екземпляри застосунку.", "Образ складається з шарів, які можуть кешуватися та спільно використовуватися. Багатостадійне складання дає змогу тримати компілятори й тестові інструменти у проміжному етапі, а кінцевий образ формувати лише з runtime-залежностей. Відтворюваність потребує фіксації базового образу, версій залежностей, контексту складання й параметрів цільової архітектури.\n\nЯкщо збірки на різних вузлах відрізняються, зіставте digest базового образу, залежності, build arguments та кеш. QA перевіряє, що у фінальному образі немає тестових секретів, непотрібних інструментів і файлів із локальної машини. Тег на кшталт latest не є незмінною ідентичністю: для доказового розгортання використовуйте digest та перевіряйте походження опублікованого артефакту.", "docker"),
  make("Площина керування та вузли Kubernetes", "Інфраструктура", "Kubernetes узгоджує бажаний стан кластера з фактичним, розподіляючи контейнери між вузлами та відновлюючи керовані ресурси.", "Площина керування приймає декларації через API, зберігає стан, планує Pods і запускає контролери. На робочих вузлах агент вузла взаємодіє з контейнерним runtime та підтримує виконання призначених Pod. Розгортання задає бажану кількість реплік, а контролер поступово створює або припиняє екземпляри, щоб наблизити фактичний стан до задекларованого.\n\nСтатус Running лише означає, що контейнер запущений; він не підтверджує готовність застосунку обслуговувати запити. QA перевіряє readiness і liveness probes, розподіл трафіку, відновлення після втрати вузла, ліміти ресурсів та поведінку під час оновлення конфігурації. Діагностика має зіставляти події кластера, стан Pod, журнали контейнера й метрики сервісу, бо одна помилка може бути наслідком планування, мережі або самого процесу.", "kube"),
  make("Контролери, декларативний стан і самовідновлення", "Інфраструктура", "Контролер Kubernetes циклічно порівнює бажаний стан ресурсу з фактичним і виконує дії для зменшення різниці між ними.", "Декларативна конфігурація описує результат, наприклад три доступні репліки, а не послідовність ручних команд. Контролер спостерігає за ресурсами й подіями, створює відсутні об’єкти або змінює їх параметри. Такий цикл не є миттєвою транзакцією: стан сходиться з часом, а помилки контролера чи залежностей можуть затримати узгодження.\n\nПід час тестування перевірте не лише початкове застосування маніфесту, а й повторне застосування, дрейф фактичного стану, часткову помилку й відкат декларації. Якщо ручна зміна зникає, це може бути очікуваною дією контролера, а не дефектом. Для QA важливо встановити, який ресурс є джерелом бажаного стану, хто його змінює і як система повідомляє про нездатність досягти потрібної конфігурації.", "kube"),
  make("Service mesh і проксі Envoy", "Інфраструктура", "Service mesh переносить частину міжсервісних мережевих функцій у керований інфраструктурний рівень, не вимагаючи вбудовувати всю політику в кожен сервіс.", "У моделі Istio площина керування розповсюджує конфігурацію, а проксі в площині даних обробляють трафік між робочими навантаженнями. Це дає змогу задавати взаємну TLS-автентифікацію, маршрути, повтори, обмеження та телеметрію. Mesh додає власні залежності, затримку й конфігурацію, тому він не усуває потребу в коректних контрактах сервісів.\n\nQA перевіряє політику дозволу та заборони, сертифікати, маршрутизацію за версіями, timeout, повторні запити й вплив проксі на заголовки. Контрольований fault injection допомагає оцінити поведінку клієнта під час відмови залежності. Необхідно перевіряти також трафік, що обходить mesh, і відповідність фактичної конфігурації проксі задекларованим правилам безпеки.", "istio"),
  make("RPC, gRPC та потокова взаємодія", "Інтеграція сервісів", "RPC оформлює віддалену операцію як виклик визначеного методу, а gRPC додає генерацію клієнтів і серверів, типізовані контракти та підтримку потоків.", "Контракт описує сервіс, параметри й результати; компілятор схеми генерує типи та транспортний код для різних мов. Виклик усе одно залежить від мережі: він має дедлайн, може бути скасований, повторений або завершитися після того, як сервер уже виконав побічну дію. Потоки дають змогу обмінюватися послідовністю повідомлень, але потребують правил завершення й контролю потоку.\n\nДля QA перевіряйте сумісність клієнтської та серверної версій, статуси помилок, дедлайни, скасування, великі повідомлення й повтори. Відокремлюйте помилку транспортного рівня від доменної помилки сервісу. Якщо виклик повторюється після timeout, перевірте ідемпотентність операції, оскільки клієнт не завжди знає, чи сервер устиг зафіксувати результат.", "grpc"),
  make("Схеми Protobuf та сумісність контрактів", "Інтеграція сервісів", "Protocol Buffers задає компактний формат структурованих повідомлень і генерує код доступу до них для різних мов програмування.", "Схема визначає поля, їхні числові ідентифікатори, типи та вкладені повідомлення. Серіалізовані дані передаються між компонентами або зберігаються, тому зміна схеми має враховувати одночасно старих споживачів, нових споживачів і вже записані повідомлення. Видалений номер поля слід резервувати, а не повторно використовувати для іншого значення.\n\nQA перевіряє сумісність у напрямках старий записувач — новий читач і новий записувач — старий читач, поведінку невідомих полів та значення за замовчуванням. Додатково важливо тестувати генерацію коду всіма підтримуваними мовами й розгортання зміни поетапно. Успішна компіляція схеми не гарантує сумісності семантики, якщо однакове поле різні компоненти трактують по-різному.", "protobuf"),
  make("Сторінки даних, буферний кеш і журналювання БД", "Системи зберігання", "Реляційна база даних перетворює запити на операції зі сторінками даних, індексами, буферним кешем і журналами відновлення.", "Табличні рядки фізично розміщуються у сторінках, які база читає з диска або знаходить у пам’яті. Зміни записуються через журналювання, що дає змогу відновити узгоджений стан після аварії; конкретний механізм залежить від рушія. Відмінність між логічною транзакцією та фізичним записом пояснює, чому успішний запит може мати різні часові характеристики залежно від кешу й дискового навантаження.\n\nПід час діагностики повільного API перевірте план запиту, читання з диска, блокування й накопичення журналу, а не лише середній час endpoint. QA відтворює холодний та прогрітий кеш, паралельні записи й аварійне переривання транзакції. Важливо перевірити, що після відновлення видимий стан відповідає правилам транзакцій, а не частково записаним проміжним даним.", "pg"),
  make("Індекси, планувальник і виконання SQL-запиту", "Системи зберігання", "Планувальник запитів обирає спосіб читання й об’єднання даних, використовуючи статистику, індекси та очікувану вартість операцій.", "Індекс прискорює певний клас запитів, але займає місце й збільшує вартість змін. Планувальник оцінює кількість рядків, порядок з’єднань і метод доступу, після чого виконувач читає сторінки, фільтрує результати й повертає рядки. Застаріла статистика або вираз, що не відповідає індексу, може привести до повного сканування таблиці.\n\nQA порівнює фактичний план і час на репрезентативних обсягах даних, перевіряє селективність умов та коректність меж пагінації. Плани не завжди стабільні після зростання даних або зміни статистики, тому слід тестувати очікувані профілі навантаження. Індекс не замінює оптимізацію моделі даних: надмірна кількість індексів уповільнює вставлення й оновлення.", "pg"),
  make("Транзакції, MVCC та рівні ізоляції", "Системи зберігання", "Транзакція групує операції в логічно узгоджену зміну, а MVCC дозволяє читачам бачити версію даних відповідно до рівня ізоляції.", "Багатоверсійний контроль конкурентності зберігає версії рядків, щоб транзакції могли працювати зі знімком даних без блокування кожного читання. Рівень ізоляції визначає, які конкурентні зміни може побачити транзакція та чи може база відхилити її для збереження серіалізованої поведінки. Точні гарантії залежать від СУБД; однакові назви рівнів не завжди означають тотожну реалізацію.\n\nПеревірте конкурентне списання залишку, повторне читання, відкат, взаємне блокування та повтор транзакції після помилки серіалізації. QA має запускати кілька клієнтів синхронно й перевіряти інваріант кінцевого стану, а не лише статус кожного запиту. Якщо застосунок повторює транзакцію автоматично, переконайтеся, що побічний ефект не дублюється.", "isolation"),
  make("Секціонування таблиць і pruning", "Системи зберігання", "Секціонування ділить логічно єдину таблицю на фізичні частини за ключем, зберігаючи доступ до них через спільне ім’я таблиці.", "Діапазонні, спискові та хеш-секції розміщують рядки за визначеним правилом. Планувальник може відкинути секції, які не відповідають умові запиту, а старі дані іноді можна від’єднати швидше, ніж видаляти рядки по одному. Секціонування не є автоматичною заміною індексу й не гарантує покращення кожного запиту; ключ має відповідати реальним фільтрам і правилам унікальності.\n\nQA перевіряє маршрутизацію вставок на межах діапазонів, запити без ключа секціонування, додавання наступної секції, pruning плану та доступність під час обслуговування. Особливо важливо тестувати перехід періоду, коли нової секції ще немає. Надмірна кількість секцій може погіршити планування запитів і збільшити навантаження на метадані.", "partition"),
  make("Шардування та ключ розподілу даних", "Розподілені сховища", "Шардування розподіляє записи логічного набору даних між кількома вузлами, щоб збільшити місткість і пропускну здатність системи.", "Маршрутизатор визначає shard за ключем розподілу або іншим правилом і спрямовує запит до потрібного вузла. Вибір ключа визначає рівномірність даних, кількість локальних запитів і можливість зберігати пов’язані записи поруч. Реплікація копіює дані всередині шарда, тоді як шардування розділяє сам набір; ці механізми вирішують різні задачі.\n\nНаприклад, користувачі можуть розподілятися за стабільним ідентифікатором, але звіти за датою вимагатимуть запитів до багатьох шардів. QA перевіряє правильність маршрутизації, унікальність, транзакції між шардами, недоступність окремого вузла та нерівномірне навантаження. Перш ніж обирати шардування, слід оцінити вертикальне масштабування, індекси й секціонування: розподілена складність має бути виправдана виміряним обмеженням.", "vitess"),
  make("Гарячі партиції та дизайн shard key", "Розподілені сховища", "Ключ розподілу визначає не лише місце запису, а й те, наскільки рівномірно навантаження розходиться між партиціями або шардами.", "Монотонно зростаючий ключ може спрямовувати поточні записи в одну вузьку частину ключового простору. Висококардинальний хешований ключ часто вирівнює запис, проте ускладнює читання за часовим діапазоном або групою сутностей. Інженерний вибір балансує гарячість запису, типові запити, локальність даних і вартість агрегації.\n\nУ навантажувальному тесті перевірте як середню швидкість, так і розподіл операцій за ключами, затримку найгарячішого сегмента та чергу запитів. Додавання випадкового суфікса може рівномірно розподілити запис, але читання тоді мусить звертатися до всіх суфіксів і об’єднувати результати. QA має тестувати цю повну ціну читання, а не оцінювати успіх лише за збільшенням write throughput.", "dynamo"),
  make("Хешування та узгоджене призначення шард", "Розподілені сховища", "Функція хешування перетворює ключ даних на значення, за яким маршрутизатор визначає вузол або діапазон зберігання.", "У простій схемі залишок від ділення хешу на кількість вузлів змушує переміщати значну частину ключів після додавання вузла. Узгоджене хешування або таблиця діапазонів дає змогу обмежити обсяг перенесення, однак потребує метаданих про власників і механізму їх узгодженого оновлення. Реальні системи часто додають віртуальні вузли, реплікацію чи окреме відображення логічного ключа на фізичний shard.\n\nПеревіряйте стабільність маршрутизації під час додавання й вилучення вузлів, версію карти шард та поведінку клієнтів із застарілими метаданими. Дві версії маршрутизатора, що по-різному трактують один ключ, можуть спричинити розділення читання та запису. Для QA важливо звіряти ключ до й після зміни топології та перевіряти, що копії переміщених даних не стають одночасно активними власниками запису.", "vitess"),
  make("Перешардування, backfill і перевірка цілісності", "Розподілені сховища", "Перешардування змінює розбиття даних між вузлами й зазвичай потребує копіювання, наздоганяння змін та контрольованого перемикання маршрутизації.", "Безпечний процес створює цільові шарди, копіює історичні дані, передає до них зміни, що надходять паралельно, і порівнює результат із джерелом. Після досягнення узгодженості маршрутизатор змінює напрямок читання й запису; залежно від системи перехід може вимагати короткого обмеження запису. Операція має бути відновлюваною після переривання та мати стан, який можна спостерігати.\n\nQA перевіряє контрольні суми, граничні ключі, паралельні оновлення, повторний запуск етапу й повернення до попередньої карти. Особливо небезпечні дублікати або втрачені зміни в момент перемикання. Навантаження під час backfill також конкурує з робочим трафіком, тому потрібно вимірювати затримку й помилки користувацьких операцій, а не лише факт завершення міграції.", "reshard"),
  make("Реплікація, кворум і узгодженість читання", "Розподілені сховища", "Реплікація зберігає копії даних на кількох вузлах, щоб підвищити доступність або пропускну здатність читання.", "Синхронна реплікація може вимагати підтвердження кількох вузлів до завершення запису, збільшуючи затримку, зате обмежуючи втрату підтверджених змін. Асинхронна реплікація швидша для записувача, але читач із відсталої копії може побачити застарілий стан. Кворум визначає, скільки учасників мають погодити операцію, однак точна гарантія залежить від протоколу й конфігурації.\n\nПеревіряйте читання одразу після запису, затримку репліки, вибір нового лідера та поведінку під час втрати одного чи кількох вузлів. Кеш або маршрутизація читання на репліки можуть створювати видиму неузгодженість на рівні API. QA фіксує, чи гарантує система read-your-writes, а також перевіряє, чи після failover не з’являються дублікати та не губляться підтверджені зміни.", "kafka"),
  make("Консенсус Raft і лідерство групи реплік", "Розподілені сховища", "Raft допомагає групі вузлів узгодити впорядкований журнал змін, навіть якщо частина вузлів тимчасово недоступна.", "У групі обирається лідер, який приймає записи та реплікує їх іншим учасникам. Запис вважається зафіксованим після підтвердження кворумом; при мережевому розділенні менша частина групи не повинна самостійно підтверджувати конфліктні зміни. Ця гарантія досягається ціною затримки мережевих раундів і запису на стабільне сховище.\n\nДля QA змоделюйте затримку, втрату зв’язку між вузлами, падіння лідера та повторне приєднання відстаючої репліки. Перевірте, які операції приймаються без кворуму, чи повертаються вони як непідтверджені та як відновлюється журнал. Низька затримка одного вузла не описує поведінку кластера: критичними є час виборів, доступність кворуму та коректність після відновлення мережі.", "raft"),
  make("Розподілені транзакції та компенсаційні процеси", "Розподілені системи", "Коли бізнес-операція охоплює кілька незалежних сервісів, її цілісність потрібно забезпечити без припущення про спільну локальну транзакцію.", "Патерн saga розкладає процес на локальні транзакції та компенсувальні дії для випадку часткової невдачі. Компенсація не завжди є точним зворотним відтворенням: повернення платежу, наприклад, може бути окремою бізнес-операцією. Оркестрація централізує послідовність кроків, тоді як хореографія передає керування подіями між учасниками.\n\nQA моделює збій після кожного кроку, затриману або дубльовану подію та повторну доставку команди. Перевіряється не лише успішний фінальний стан, а й те, чи видно користувачу проміжний статус та чи справді виконані компенсації. Ідемпотентність і кореляційні ідентифікатори потрібні для безпечного повтору та реконструкції історії процесу.", "kafka"),
  make("Кешування, TTL та інвалідація", "Швидкодія та кешування", "Кеш зберігає копію даних ближче до споживача, щоб зменшити повторне навантаження на дорожче джерело та скоротити час відповіді.", "Кеш може працювати в процесі, окремим сервером або на краю мережі. Політика TTL обмежує час життя копії, а інвалідація намагається прибрати її після зміни джерела. Кешування додає компроміс між свіжістю, доступністю й вартістю обчислення; воно не стає автоматично безпечним лише тому, що дані можна відновити.\n\nQA перевіряє промах, застарілий запис, одночасне завершення TTL, інвалідацію після оновлення та поведінку при відмові кеша. Наприклад, кеш-ключ без ідентифікатора користувача може повернути приватне представлення іншому клієнту. Тестуйте холодний і прогрітий шлях, а також навантаження під час масового протухання ключів, коли багато запитів одночасно звертаються до бази.", "redis"),
  make("Черги повідомлень і підтвердження доставки", "Асинхронна взаємодія", "Брокер повідомлень відокремлює відправника від споживача в часі й допомагає керувати чергою роботи під час нерівномірного навантаження.", "Відправник публікує повідомлення, маршрутизатор брокера спрямовує його до черги, а споживач підтверджує обробку. Підтвердження після завершення дає модель щонайменше одноразової доставки: збій між виконанням побічного ефекту та підтвердженням може привести до повтору. Тому споживачеві потрібні ідемпотентність, контроль повторів і окрема політика для невиправних повідомлень.\n\nQA перевіряє порядок у межах потрібної гарантії, redelivery, dead-letter маршрут, затримку черги й поведінку споживача під час перезапуску. Підтвердження до фактичного запису результату створює ризик втрати повідомлення, а надто пізнє підтвердження — дублювання. Метрики backlog і віку найстарішого повідомлення часто показують деградацію раніше, ніж API починає повертати помилки.", "rabbit"),
  make("Журнал подій Kafka, партиції та consumer groups", "Асинхронна взаємодія", "Kafka зберігає події в упорядкованих партиціях журналу й дає змогу групам споживачів читати та обробляти їх незалежно.", "Порядок гарантовано всередині окремої партиції, а ключ події впливає на розподіл записів. Споживач зберігає позицію читання й може продовжити після перезапуску; повторна обробка можлива залежно від моменту фіксації позиції та побічного ефекту. Реплікація партицій підвищує стійкість, але не скасовує потребу перевіряти відставання й доступність лідера.\n\nQA перевіряє ключування подій, порядок, повторне читання, балансування споживачів і сумісність схеми. Якщо споживач записує в базу до збереження offset, аварія може викликати повтор; якщо offset зберігається раніше — подія може бути пропущена. Порівняйте число опублікованих, прочитаних і фактично застосованих подій, а не лише успішну відповідь брокера.", "kafka"),
  make("Об’єктне сховище та версійність об’єктів", "Платформи даних", "Об’єктне сховище зберігає великі файли як об’єкти з ключем і метаданими, доступні через API, а не як блоки чи звичайні рядки бази даних.", "Такий підхід підходить для резервних копій, медіафайлів, журналів і аналітичних наборів. Ключ об’єкта задає його адресу, а політика доступу визначає, хто може читати, записувати або видаляти вміст. Версійність і lifecycle-правила можуть спростити відновлення та архівування, але змінюють вартість зберігання й поведінку видалення.\n\nQA перевіряє контроль доступу, завантаження частинами, цілісність контрольної суми, повторне завантаження, перервану передачу та збереження потрібної версії. Важливо перевірити, чи прикладний сервіс не робить об’єкт публічним через неправильну політику або URL. Відповідь успішного PUT не гарантує, що подальший CDN чи кеш одразу бачить ту саму версію.", "s3"),
  make("Lakehouse і табличний формат Apache Iceberg", "Платформи даних", "Lakehouse поєднує дешеве файлове зберігання аналітичних даних із метаданими та транзакційними можливостями табличного шару.", "Формат на кшталт Iceberg веде метадані таблиці, snapshot-и й маніфести файлів, завдяки чому різні рушії можуть погоджено читати та змінювати великі набори Parquet, Avro або ORC. Схема та розбиття можуть еволюціонувати без ручного переписування кожного файла. Фактичні гарантії залежать від каталогу метаданих, координації запису й сумісності обчислювальних рушіїв.\n\nQA перевіряє конкурентних записувачів, атомарність публікації snapshot-а, еволюцію схеми, rollback і читання тієї самої таблиці різними рушіями. Окремо важливо виявляти orphan-файли й некоректне очищення старих snapshot-ів. Сумісність формату не означає, що всі рушії однаково підтримують кожну можливість або версію специфікації.", "iceberg"),
  make("Розподілене пакетне обчислення Apache Spark", "Платформи даних", "Apache Spark виконує обчислювальні задачі паралельно на кластері, розподіляючи їх між процесами виконавців і вузлами даних.", "Driver будує план застосунку та координує його виконання, менеджер кластера виділяє ресурси, а executors виконують задачі й можуть кешувати проміжні дані. План поділяється на стадії за залежностями; обмін між ними може спричинити shuffle і значне мережеве навантаження. Повторне виконання задач після втрати виконавця потребує, щоб операції були безпечними до повтору або мали контрольований запис результату.\n\nQA перевіряє обробку порожніх, дубльованих і перекошених даних, повтор задач, shuffle, checkpoint та відновлення driver-а. Локальне виконання не відтворює повністю мережеві та ресурсні обмеження кластера. Для діагностики зіставляйте план, журнал задач, використання пам’яті, spill на диск і вихідні контрольні суми.", "spark"),
  make("Потокова обробка та вікна подій", "Платформи даних", "Потоковий рушій обробляє події в міру їх надходження й підтримує обчислення над часовими вікнами або станом між подіями.", "Подія має час надходження до системи й часто окремий event time, коли факт стався в предметному світі. Відкладені та повторно доставлені події вимагають watermark-ів, правил запізнення, checkpoint-ів і узгодження стану. Гарантія exactly-once має конкретну межу: внутрішнє обчислення може бути атомарним, але зовнішній побічний ефект залежить від sink і протоколу запису.\n\nQA створює упорядковані та запізнілі події, дублікати, пропуски й повторний запуск після збою. Перевірте, чи підсумок вікна змінюється в межах визначеного часу й чи коректно обробляється подія після watermark-а. Метрики відставання, розміру стану й частоти checkpoint-ів допомагають відрізнити повільний потік від некоректного результату.", "kafka"),
  make("Оркестрація робочих процесів Apache Airflow", "Платформи даних", "Airflow планує графи залежних задач і відстежує їхні запуски, надаючи операторам контроль над повтором і відновленням пакетних процесів.", "DAG описує залежності, а task instance є виконанням конкретної задачі для логічного інтервалу даних. Логічна дата не обов’язково збігається з фактичним часом старту; повтори, backfill і catchup можуть виконати ту саму задачу повторно. Планувальник визначає придатні запуски, а виконавець передає завдання доступному worker-у.\n\nQA перевіряє межі інтервалу, часові пояси, повтори, пропущені розклади, backfill та ідемпотентність вихідного запису. Наприклад, повторне завдання має оновити визначену партицію, а не створити дубль. Перевіряйте також секрети, ізоляцію середовищ і те, чи сигналізує система про довге очікування залежності, а не лише про помилку самої задачі.", "airflow"),
  make("Спостережуваність: метрики, журнали й траси", "Експлуатація", "Спостережуваність поєднує метрики, журнали та розподілені траси, щоб виводити внутрішній стан системи зі зовнішніх сигналів.", "Метрика агрегує числове вимірювання у часі, журнал фіксує подію, а trace пов’язує роботу кількох компонентів одним причинним шляхом. Контекстні ідентифікатори дають змогу перейти від зростання затримки до конкретного запиту й відповідних логів. OpenTelemetry стандартизує інструментування та передавання сигналів, але збирання, зберігання й візуалізація можуть виконуватися різними системами.\n\nQA перевіряє наявність кореляційного ідентифікатора, точність статусу, відсутність секретів у логах та коректність метрик для помилкових і успішних шляхів. Висока cardinality міток може різко збільшити вартість зберігання. Якщо trace обривається на шлюзі, це не доводить, що внутрішня операція не виконувалася: потрібно узгодити семплювання та поширення контексту між сервісами.", "otel"),
  make("Безпечні випуски: canary, blue-green і відкат", "Експлуатація", "Стратегія випуску визначає, як нова версія отримує трафік і як команда обмежує наслідки регресії.", "Blue-green утримує дві узгоджені інфраструктури та перемикає трафік між ними, тоді як canary поступово збільшує частку запитів до нової версії. Відкат застосунку не завжди повертає схему бази чи зовнішній побічний ефект, тому міграції мають підтримувати перехідний період сумісності. Автоматичний gate може оцінювати помилки, затримку та бізнес-метрики перед розширенням трафіку.\n\nQA перевіряє маршрутизацію за версіями, сесії, сумісність даних, критерій зупинки та поведінку під час відкату. Контрольний тест має довести, що стара й нова версії можуть працювати одночасно, якщо цього вимагає схема випуску. Показник успіху лише на синтетичному health endpoint не гарантує відсутності регресії в реальному сценарії користувача.", "kube"),
  make("Навчання моделі та версіонування артефактів", "Машинне навчання", "Навчання моделі підбирає параметри за прикладами даних, а відтворюваний конвеєр зберігає зв’язок між даними, кодом, параметрами й отриманим артефактом.", "Типовий цикл включає підготовку набору, поділ на train, validation і test, визначення функції втрат, оптимізацію ваг та оцінювання на відкладених даних. Розділення запобігає витоку цільової інформації, але саме по собі не усуває зміщення вибірки. Збережений файл ваг потребує разом із собою версії архітектури, tokenizer-а, залежностей і схеми вхідних ознак.\n\nQA перевіряє відтворюваність запуску, детермінованість там, де вона очікується, контроль витоку даних і відповідність метрик заданому набору. Порівнюйте модель із базовою лінією, а не лише з попереднім експериментом. Високий показник на тесті не доводить готовність до production, якщо тестові дані не представляють майбутній розподіл запитів.", "pytorch"),
  make("Обслуговування датасетів і контроль якості даних", "Машинне навчання", "Якість моделі обмежена якістю даних, а тому виробничий ML-конвеєр має контролювати походження, схему й зміни розподілу прикладів.", "Дані проходять збір, валідацію, очищення, маркування, трансформацію та версіонування. Помилки можуть з’явитися через пропущені поля, зміну одиниць, дублікати, неточні мітки або представлення персональної інформації. Data lineage пов’язує навчальний набір із джерелом та трансформаціями й полегшує повторне відтворення моделі.\n\nQA перевіряє контракти схеми, діапазони, частку пропусків, баланс класів, дублікати між train і test та доступ до чутливих атрибутів. Порівняння статистик між періодами може виявити drift до погіршення бізнес-результату. Не слід автоматично виправляти аномальні значення без збереження походження: таке очищення здатне прибрати рідкісний, але важливий випадок.", "pytorch"),
  make("GPU, CUDA та прискорення обчислень", "Машинне навчання", "GPU прискорює паралельні матричні операції, але перенесення даних і планування обчислень між CPU та GPU також впливають на загальну затримку.", "Фреймворк розміщує тензори на обраному пристрої та подає ядра виконання потокам CUDA. Операції можуть виконуватися асинхронно, тому вимірювання лише часу повернення виклику CPU дає хибну оцінку. Розподілене навчання додає синхронізацію градієнтів, передачу даних між GPU та вимоги до узгодженості версій драйверів і бібліотек.\n\nQA фіксує модель GPU, драйвер, CUDA runtime, тип точності й розмір пакета; перевіряє числову похибку, пропускну здатність, споживання пам’яті й поведінку при нестачі ресурсів. Результати FP16, BF16 або TF32 можуть відрізнятися від повної точності. Для чесного бенчмарку потрібні прогрів, синхронізація та повтори на тому самому профілі навантаження.", "pytorch"),
  make("Архітектура Transformer та механізм уваги", "Машинне навчання", "Transformer обчислює контекстні представлення послідовностей за механізмом уваги й став базовою архітектурою багатьох сучасних мовних моделей.", "Механізм self-attention зіставляє запит, ключі та значення токенів, щоб формувати зважений контекст. Кілька голів уваги дають змогу моделі опрацьовувати різні типи взаємозв’язків, а позиційне кодування додає інформацію про порядок. Під час навчання параметри підбираються за великою кількістю прикладів; під час генерації авторегресивна модель послідовно передбачає наступний токен за попереднім контекстом.\n\nДля QA важливо перевіряти крайні довжини, багатомовні входи, спеціальні маркери, обрізання контексту й детермінованість там, де вона налаштована. Помилка на довгій послідовності може бути наслідком tokenizer-а, вікна контексту чи пам’яті уваги. Архітектура визначає механізм обчислення, але не гарантує фактичну точність, безпечність або актуальність відповіді моделі.", "transformer"),
  make("Токенізація та вікно контексту LLM", "Машинне навчання", "Токенізатор перетворює текст на послідовність числових ідентифікаторів, якими оперує мовна модель.", "Конвеєр може нормалізувати текст, попередньо розбити його, застосувати алгоритм на кшталт BPE або WordPiece та додати спеціальні токени. Токен не дорівнює слову: його кількість залежить від мови, пунктуації й словника конкретної моделі. Вікно контексту обмежує число токенів у сумі системних інструкцій, історії, документів і відповіді.\n\nQA перевіряє Unicode, пробіли, змішану мову, спеціальні маркери й поведінку на межі вікна. Занадто раннє обрізання може видалити важливу умову з початку або кінця документа, а неочікувано довгі токенізації збільшують вартість та затримку. Для відтворення результату зберігайте версію tokenizer-а та точні правила формування контексту.", "tokenizer"),
  make("Векторні embeddings і семантичне подання", "Машинне навчання", "Embedding перетворює об’єкт на числовий вектор, у якому геометрична близькість може відображати семантичну подібність для конкретного завдання.", "Embedding-модель кодує текст, зображення чи інший об’єкт у вектор фіксованої розмірності. Пошук може порівнювати вектори за косинусною відстанню, скалярним добутком або евклідовою відстанню. Значення вектора має сенс лише разом із версією моделі, способом нормалізації, мовою та доменом даних; однаковий текст, закодований різними моделями, не обов’язково сумісний.\n\nQA формує набір релевантних і нерелевантних пар та перевіряє ранжування, мову, дублікати й зміни після оновлення моделі. Перевірте також, що повторна індексація не змішує вектори старого й нового простору. Висока семантична близькість не є доказом логічної тотожності, тому retrieval-рішення слід оцінювати на предметних прикладах.", "embeddings"),
  make("Векторні індекси та пошук найближчих сусідів", "Машинне навчання", "Векторний індекс прискорює пошук об’єктів, найближчих до запиту у багатовимірному просторі, обмінюючи частину повноти на швидкість.", "Точний пошук порівнює запит із кожним вектором, а наближені структури на кшталт HNSW чи IVF скорочують кількість кандидатів. Параметри індексу визначають компроміс між затримкою, пам’яттю, часом побудови та recall. Фільтри за правами доступу чи категоріями можуть виконуватися до або після пошуку, і це змінює як продуктивність, так і набір повернених результатів.\n\nQA вимірює recall@k та якість ранжування на зафіксованому наборі запитів, перевіряє порожній індекс, оновлення, видалення й фільтрацію. Після додавання наближеного індексу результат може відрізнятися від точного пошуку; це очікуваний компроміс, який потрібно виміряти. Також перевіряйте, чи не потрапляють результати іншого користувача через застосування фільтра вже після retrieval.", "pgvector"),
  make("Retrieval-Augmented Generation і джерела знань", "Системи LLM", "RAG поєднує генеративну модель із пошуком у зовнішньому корпусі, щоб передавати їй релевантний контекст для відповіді.", "Конвеєр зазвичай очищає й ділить документи, створює embeddings, знаходить кандидатів за запитом і передає відібрані фрагменти мовній моделі. Такий підхід полегшує оновлення знань та атрибуцію джерел, але не гарантує, що пошук знайде правильний уривок або модель точно його використає. Розмір фрагмента, перекриття, reranking і доступність метаданих впливають на recall і наявність контексту.\n\nQA перевіряє окремо retrieval і генерацію: чи знайдено потрібний документ, чи збережені права доступу, чи відповідає текст джерелам і чи модель відмовляється за браку доказів. Додайте випадки з конфліктними документами, застарілими версіями та інструкціями всередині retrieved content. Трасування має зберігати ідентифікатори документів, версії індексу й фактичні фрагменти, використані для відповіді.", "rag"),
  make("Виклик інструментів і runtime агентної системи", "Системи LLM", "Виклик інструментів дає моделі змогу запропонувати структуровану дію, але саме прикладний runtime має перевірити й виконати її в межах дозволів.", "Модель повертає назву функції та аргументи відповідно до описаної схеми; серверна логіка валідує аргументи, авторизацію, межі ресурсів і лише потім виконує операцію. Результат повертається моделі для наступного кроку. Агентний цикл може містити кілька таких ходів, тому потребує ліміту кроків, таймауту, журналювання й визначеного правила завершення.\n\nQA перевіряє невідомий інструмент, некоректні аргументи, відмову залежності, повторний виклик і спробу дії без прав. Текст моделі не є виконуваним повноваженням; критичні операції мають окремо санкціонуватися runtime. Трасуйте кожне рішення, виклик і результат, щоб відрізнити помилку планування моделі від дефекту інтеграції або бізнес-інструмента.", "tools"),
  make("Обслуговування LLM: batching, KV-кеш і масштабування", "Системи LLM", "Inference-сервер розподіляє запити моделі між обчислювальними ресурсами та керує пам’яттю, щоб узгодити пропускну здатність із затримкою.", "Під час генерації модель повторно використовує key-value кеш попередніх токенів. Continuous batching додає нові запити в робочий пакет у міру завершення інших, а paged-підхід до KV-пам’яті зменшує фрагментацію. Вибір batch, максимального контексту, точності ваг і паралелізму впливає на пам’ять GPU та чергу очікування; максимальна пропускна здатність може збільшити затримку окремого запиту.\n\nQA вимірює час до першого токена, час між токенами, повну затримку, пропускну здатність і помилки при вичерпанні пам’яті. Тестуйте короткі та довгі контексти, конкурентні потоки, скасування клієнтом і повторне використання префікса. Порівнюйте результати для конкретної версії моделі й налаштувань, оскільки оптимізації можуть змінити числову точність або порядок вибору токенів.", "vllm"),
  make("Оцінювання якості моделей та LLM-застосунків", "Системи LLM", "Оцінювання вимірює, наскільки система відповідає визначеним критеріям на фіксованому наборі прикладів, а не покладається на враження від кількох відповідей.", "Набір оцінювання має представляти типові запити, крайні випадки, помилки й небезпечні сценарії. Автоматичні метрики можуть оцінити точність, формат або retrieval, але судження іншої моделі також має похибку й потребує калібрування на людській оцінці. Порівняння версій потребує незмінних вхідних даних, критеріїв і задокументованих параметрів генерації.\n\nQA розділяє якість моделі, пошуку, prompt-у та зовнішніх інструментів, а потім додає інтеграційні показники затримки, вартості й частоти відмов. Перевіряйте статистичну значущість різниці й зберігайте невдалі приклади як нові регресійні випадки. Середній бал не повинен приховувати критичну помилку на невеликій, але важливій групі запитів.", "eval"),
  make("Захист LLM: prompt injection і межі довіри", "Системи LLM", "Prompt injection виникає, коли вхідний або retrieved текст містить інструкції, що намагаються змінити поведінку моделі чи спонукати її до несанкціонованої дії.", "Мовна модель обробляє системні інструкції, текст користувача й зовнішній вміст у спільному контексті; розмежування довіри не є криптографічною гарантією. Непряма ін’єкція може міститися в документі, вебсторінці або листі, який система лише читає. Тому захист має спиратися на ізоляцію даних, перевірки інструментів, мінімальні повноваження й обмеження побічних ефектів, а не лише на формулювання prompt-у.\n\nQA перевіряє спроби витягнути секрет, змусити виконати інструмент, обійти політику через цитований текст і передати небезпечний вміст між етапами. Кожна дія має повторно перевірятися сервером за ідентичністю та ресурсом. Логи не повинні зберігати чутливий prompt або секрети без підстав; водночас система має залишати достатньо безпечних доказів для розслідування.", "owasp"),
  make("Безперервний моніторинг ML-моделі в production", "Системи LLM", "Якість моделі після випуску залежить від того, наскільки виробничий потік даних зберігає властивості навчального й оцінювального середовища.", "Data drift змінює розподіл вхідних ознак, а concept drift — зв’язок між ознаками та цільовим результатом. Для генеративної системи додатково відстежують частоту відмов, використання інструментів, довжину контексту, затримку, вартість і оцінки корисності. Метрики мають бути прив’язані до версії моделі, prompt-у, індексу й набору даних, інакше причину деградації важко локалізувати.\n\nQA перевіряє, чи зберігається контрольований набір запитів після кожної зміни, як виявляються зміщення сегментів і хто реагує на поріг. Моніторинг не повинен збирати зайві персональні дані; потрібні маскування та обмежений строк зберігання. Після виявлення деградації система має підтримувати безпечне повернення до попередньої версії або вимкнення функції без втрати основного сервісу.", "eval"),
];

